import{z as A,x as B,o as n,c as p,q as l,j as i,D as E,d as r,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"财政-货币主导","description":"","frontmatter":{"title":"财政-货币主导","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fiscal-monetary-dominance.md","filePath":"econ/fiscal-monetary-dominance.md","lastUpdated":1791063341000}'),d={name:"econ/fiscal-monetary-dominance.md"};function m(c,a,D,h,u,f){const t=B("Mermaid");return n(),p("div",null,[a[2]||(a[2]=l('<h1 id="财政-货币主导" tabindex="-1">财政-货币主导 <a class="header-anchor" href="#财政-货币主导" aria-label="Permalink to &quot;财政-货币主导&quot;">​</a></h1><div class="epigraph"><p>价格水平由谁的规则钉住：货币主导下财政必须最终适应；财政主导下货币适应债，通胀成为清算工具。</p><footer>—— Sargent and Wallace, Some Unpleasant Monetarist Arithmetic, 1981；Leeper, Equilibria under Active and Passive Monetary and Fiscal Policies, JME 1991</footer></div><p><a href="/econ/debt-sustainability">上一课</a>的 \\(s\\) 反应函数被当成给定。本课缺口是 <strong>谁适应谁</strong>：Sargent–Wallace 的算术与 Leeper 的主动/被动。不重写 \\(r-g\\) 公式，不把 CBDC 提前当主工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>货币数量或泰勒规则要钉住价格，政府跨期预算必须在某个未来用税收或支出闭合——否则债爆炸或靠铸币税。Sargent–Wallace：若财政不适应，紧货币今天可以意味着更高的未来通胀。Leeper：主动货币+被动财政，或被动货币+主动财政，才能有唯一（局部）均衡；两个都主动则冲突。缺口是给锚定课的「财政可以解钉」一条规则语言。</p><p><span class="marginnote">Sargent and Wallace, FRB Minneapolis <em>Quarterly Review</em> 1981。Leeper, <em>JME</em> 1991。Woodford 的财政理论讨论。Cochrane 的 FTPL 是有争议的延伸，本课用 Leeper 的主动被动，不把争论写成已决。</span></p><p><span class="marginnote">「主动/被动」是规则分工的行话：主动=自己定目标、不理别人（央行铁了心控通胀，或财政花钱不追着债跑）；被动=围着对方调整自己的规则。必须恰好一方主动、另一方被动，均衡才有锚；两人都想说了算或两人都互相等，价格就悬了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线性 NK 加政府预算。货币规则：对通胀的反应 \\(\\phi_\\pi\\)。财政：盈余对债的反应 \\(\\gamma\\)。BK 式计数：一对一的主动被动组合给出决定性。财政主导：盈余不跟债走，价格水平跳升以稀释名义债，使预算闭合（财政价格理论的核心机制）。再谈判、指数化债、外币债削弱稀释通道，把经济推向 Arellano 违约。</p>',9)),(n(),i(s,null,{default:E(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20AM%5B%22%E4%B8%BB%E5%8A%A8%E8%B4%A7%E5%B8%81%22%5D%20--%3E%20NEED%5B%22%E9%9C%80%E8%A6%81%E8%A2%AB%E5%8A%A8%E8%B4%A2%E6%94%BF%22%5D%0A%20%20AF%5B%22%E4%B8%BB%E5%8A%A8%E8%B4%A2%E6%94%BF%22%5D%20--%3E%20NEED2%5B%22%E9%9C%80%E8%A6%81%E8%A2%AB%E5%8A%A8%E8%B4%A7%E5%B8%81%22%5D%0A%20%20BOTH%5B%22%E5%8F%8C%E4%B8%BB%E5%8A%A8%22%5D%20--%3E%20CONF%5B%22%E5%86%B2%E7%AA%81%20%2F%20%E4%B8%8D%E5%AE%9A%E6%88%96%E7%88%86%E7%82%B8%22%5D%0A%20%20DOM%5B%22%E8%B4%A2%E6%94%BF%E4%B8%BB%E5%AF%BC%22%5D%20--%3E%20INF%5B%22%E9%80%9A%E8%83%80%E6%B8%85%E7%AE%97%E5%90%8D%E4%B9%89%E5%80%BA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与沟通：Delphic 若揭示「财政不会适应」，锚定失败。与 HANK：稀释的分配取决于谁持有名义债（Doepke–Schneider）。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：政府欠 100 万亿名义债，若物价水平突然翻倍，同样一笔国债的实际购买力缩成一半——等于悄悄赖掉 50 万亿的账。这就是「通胀清算」：不违约、不赖账，但持债人的钱变毛了。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是跨期预算必须在均衡成立。不是规范上「应该违约或应该征税」，而是价格、违约、或盈余三者必居其一（或组合）。非常规货币扩张央行持有的政府债，把利息风险移到公共部门，主导问题更显性——后课资产负债表。独立央行是承诺装置，不能单独取消算术。",-1)),(n(),i(s,null,{default:E(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20GAP%5B%22%E6%94%BF%E5%BA%9C%E8%B7%A8%E6%9C%9F%E9%A2%84%E7%AE%97%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20Q%5B%22%E9%9D%A0%E4%BB%80%E4%B9%88%E9%97%AD%E5%90%88%EF%BC%9F%22%5D%0A%20%20Q%20--%3E%20SUR%5B%22%E5%8A%A0%E7%A8%8E%E5%87%8F%E6%94%AF%EF%BC%9A%E7%9B%88%E4%BD%99%E8%B0%83%E6%95%B4%22%5D%0A%20%20Q%20--%3E%20DEF%5B%22%E8%BF%9D%E7%BA%A6%EF%BC%9A%E6%8B%92%E4%BB%98%E9%83%A8%E5%88%86%E5%80%BA%E5%8A%A1%22%5D%0A%20%20Q%20--%3E%20INF%5B%22%E9%80%9A%E8%83%80%EF%BC%9A%E7%A8%80%E9%87%8A%E5%90%8D%E4%B9%89%E5%80%BA%22%5D%0A%20%20SUR%20--%3E%20EQ%5B%22%E5%9D%87%E8%A1%A1%E6%81%A2%E5%A4%8D%22%5D%0A%20%20DEF%20--%3E%20EQ%0A%20%20INF%20--%3E%20EQ%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">初学者容易以为紧货币总能压住通胀。Sargent–Wallace 提醒：如果财政部坚持不增收减支，今天的紧货币推高利息负担，市场反而预期央行将来被迫放水买单——紧现在、松未来，总账未必更紧。</span></p><p>不快的算术：今天的反通胀若提高实际利率、加重债，而财政不跟，人会预期未来的货币投降。</p><p><span class="marginnote">时间不一致课的通胀偏误是另一条线（Barro–Gordon）。本课是预算闭合，不是菲利普斯欺骗。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不主张「任意债都可以靠物价一次跳清」。流动性陷阱、ZLB、长期债的估值效应使定量复杂。下一课用历史看银行危机，不是同一条会计。不把黄金作为货币规则重写。</p><p>后课默认：决定性要声明货币与财政谁主动；财政主导是通胀清算名义债。下一课：银行危机的历史模式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不愉快算术：财政不适应时，紧货币可预示未来通胀。</li><li>Leeper：主动/被动配对才能局部决定。</li><li>稀释、违约、增税是预算闭合的三个出口。</li><li>出处：Sargent and Wallace 1981；</li></ul>',8))])}const g=A(d,[["render",m]]);export{_ as __pageData,g as default};
